('SAT_WINE_001','BLANCO',1,$lbl$Vino blanco — práctica 1$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_001", "priority": 1, "grape_variety": "Chardonnay", "region": "Chablis", "country": "France", "style": "Dry, high acidity, light-medium body, unoaked or minimal oak. Pale lemon colour, citrus and green apple primary aromas, possible lees/mineral impression.", "expected_sat_observations": {"appearance": ["Pale lemon colour", "Clear", "Light to medium intensity"], "nose": ["Clean condition", "Medium intensity", "Citrus (lemon, lime), green apple", "Possible wet stone or lees notes", "Young development"], "palate": ["Dry sweetness", "High acidity", "Light to medium body", "Citrus and green apple flavours", "Medium finish", "No obvious oak or butter notes"], "conclusions": ["Good to Very Good quality (when well-made)", "Drink now; may age 3-5 years in better vintages"]}, "common_student_errors": ["Calling it Sauvignon Blanc automatically due to green aromas", "Ignoring lack of herbaceous intensity as diagnostic", "Marking quality as low because fruit is restrained", "Confusing high acidity with underripeness", "Missing mineral/lees character as positive indicator"], "misconceptions_addressed": [{"misconception": "All Chardonnay is oaky", "correction": "Chablis exemplifies Chardonnay in its most neutral form, relying on variety and terroir rather than winemaking"}, {"misconception": "Low aroma intensity means low quality", "correction": "Restrained, precise aromatics combined with high acidity and good structure indicate quality in cool-climate whites"}, {"misconception": "Chablis and Sauvignon Blanc are confused", "correction": "Chablis (Chardonnay) shows citrus without herbaceous intensity; Sauvignon Blanc shows tropical/herbaceous notes"}], "coaching_hints": ["Is the wine neutral, or is it precise and balanced?", "Notice the acidity on the finish — does it support or undermine quality?", "Can you identify primary fruit without secondary winemaking notes?", "What role does the cool climate play in the final structure?"], "causal_reasoning_paths": [{"cause": "Cool climate", "effect": "High acidity and restrained fruit maturity", "example_in_wine": "Chablis shows vibrant acidity and citrus rather than ripe stone fruit"}, {"cause": "Minimal oak/lees contact", "effect": "Neutral aromatic profile without butter or toast", "example_in_wine": "Pure varietal character without secondary complexity"}, {"cause": "Limestone terroir (Kimmeridgian)", "effect": "Mineral or flinty character in nose and palate", "example_in_wine": "Possible wet stone or chalk impressions"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_002','BLANCO',1,$lbl$Vino blanco — práctica 2$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_002", "priority": 1, "grape_variety": "Chardonnay", "region": "Côte de Beaune / Mâconnais", "country": "France", "style": "Dry, medium to full body, oak/lees texture possible, ripe citrus and stone fruit. Medium lemon colour, butter and toast secondary notes.", "expected_sat_observations": {"appearance": ["Medium lemon to gold colour", "Clear", "Medium to deep intensity"], "nose": ["Clean condition", "Medium to pronounced intensity", "Stone fruit (peach, apricot), ripe citrus", "Butter, toast, possible creamy/lees notes", "Medium development"], "palate": ["Dry sweetness", "Medium acidity", "Medium to full body", "Stone fruit and citrus flavours", "Butter, oak and creamy texture", "Medium to long finish"], "conclusions": ["Good to Very Good quality", "Drink now to medium-term ageing (5-7 years)"]}, "common_student_errors": ["Calling sweetness because of full body and oak", "Listing oak but not explaining why it's there", "Missing quality assessment based on texture and length", "Confusing oak-derived aromas with primary fruit", "Underestimating complexity due to oaky character"], "misconceptions_addressed": [{"misconception": "All Burgundy white is the same", "correction": "Chablis, Côte de Beaune, and Mâconnais each have distinct styles based on ripeness and winemaking"}, {"misconception": "Oak always means poor quality", "correction": "Well-integrated oak in Burgundy whites adds texture and complexity when balanced by acidity"}, {"misconception": "Full body and butter mean sweetness", "correction": "These are winemaking effects (MLF, oak, lees) not sugar; acidity confirms dryness"}], "coaching_hints": ["Separate primary fruit from secondary winemaking notes.", "Does the oak feel integrated or dominant?", "How does acidity balance the richness of the wine?", "What tells you this is quality despite the richness?"], "causal_reasoning_paths": [{"cause": "Warmer terroir within Burgundy", "effect": "Riper fruit (stone fruit instead of citrus only)", "example_in_wine": "Mâcon shows riper stone fruit than Chablis"}, {"cause": "Oak maturation and lees contact", "effect": "Butter, toast, creamy texture; increased complexity", "example_in_wine": "Secondary aromas of butter and toasted bread"}, {"cause": "Malolactic conversion", "effect": "Reduced acidity sharpness, increased butter/creaminess", "example_in_wine": "Medium acidity despite cool climate"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_003','BLANCO',1,$lbl$Vino blanco — práctica 3$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_003", "priority": 1, "grape_variety": "Riesling", "region": "Mosel", "country": "Germany", "style": "Off-dry to medium-sweet, high acidity, low alcohol (8-9%), floral and citrus aromas. Pale lemon colour, stone fruit and green apple notes.", "expected_sat_observations": {"appearance": ["Pale lemon colour", "Clear", "Light intensity"], "nose": ["Clean condition", "Medium intensity", "Citrus (lemon, lime), green apple, peach", "Floral notes (rose, honeysuckle)", "Stone fruit (apricot)", "Possible lees/mineral notes", "Young to medium development"], "palate": ["Off-dry to medium-sweet", "High acidity", "Light body", "Low alcohol evident", "Citrus, apple, peach flavours", "Good length despite sweetness"], "conclusions": ["Good to Very Good quality", "Excellent ageing potential despite sweetness"]}, "common_student_errors": ["Marking acidity as medium because sweetness softens perception", "Assuming sweetness equals poor quality", "Missing balance between sweetness and acidity", "Underestimating ageing potential", "Confusing Riesling with Sauvignon Blanc"], "misconceptions_addressed": [{"misconception": "Sweet wine always means low quality", "correction": "Off-dry Riesling with high acidity and complexity demonstrates that sweetness is a style choice, not a quality marker"}, {"misconception": "Low alcohol means simple wine", "correction": "Low alcohol Riesling can show great complexity, finesse and ageing potential"}, {"misconception": "Sweetness masks acidity perception", "correction": "High acidity in Riesling counterbalances residual sugar and is critical to quality assessment"}], "coaching_hints": ["Are the sweetness and acidity in balance?", "How does acidity support quality despite the residual sugar?", "What indicates ageing potential in this sweet wine?", "Notice the low alcohol — what does this tell you about the vintage/harvest timing?"], "causal_reasoning_paths": [{"cause": "Cool Mosel climate", "effect": "High acidity retained; low sugar accumulation; low alcohol results", "example_in_wine": "Off-dry style with 8-9% alcohol and high acidity"}, {"cause": "Harvest timing (botrytis risk without full noble rot)", "effect": "Residual sugar balanced by natural acidity", "example_in_wine": "Sweet-acid balance creates harmony"}, {"cause": "Schist terroir and mineral soils", "effect": "Mineral character and stone fruit aromatics", "example_in_wine": "Possible flinty or slate impressions"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_004','BLANCO',1,$lbl$Vino blanco — práctica 4$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_004", "priority": 1, "grape_variety": "Sauvignon Blanc", "region": "Marlborough", "country": "New Zealand", "style": "Dry, high acidity, intense herbaceous and tropical aromatics. Pale yellow colour, pronounced thiol expression.", "expected_sat_observations": {"appearance": ["Pale yellow colour", "Clear", "Light to medium intensity"], "nose": ["Clean condition", "Pronounced intensity", "Citrus (lime, grapefruit)", "Tropical fruit (passion fruit, gooseberry)", "Herbaceous notes (grass, fresh herbs, nettle)", "Young development"], "palate": ["Dry sweetness", "High acidity", "Light to medium body", "Citrus and tropical flavours", "Herbaceous character", "Medium to long finish", "Pronounced flavour intensity"], "conclusions": ["Good to Very Good quality", "Drink now; not intended for ageing"]}, "common_student_errors": ["Calling it Riesling due to acidity alone", "Treating green notes as fault or underripeness", "Missing intensity as a quality factor", "Confusing herbaceous (positive) with vegetal (fault)", "Underestimating aromatic profile complexity"], "misconceptions_addressed": [{"misconception": "High acidity always equals Riesling", "correction": "Aromatic profile (herbaceous/tropical vs floral/petrol) distinguishes Sauvignon Blanc from Riesling"}, {"misconception": "Green aromas mean underripe wine", "correction": "Sauvignon Blanc's herbaceous character is varietal expression and terroir, not underripeness"}, {"misconception": "Intense aromatics mean expensive wine", "correction": "Marlborough Sauvignon Blanc's value lies in clear varietal expression despite modest price"}], "coaching_hints": ["Compare the aromatic profile: is it herbaceous/tropical or floral/petrol?", "How does intensity contribute to quality assessment?", "Distinguish between herbaceous (positive) and vegetal (fault).", "What climate and winemaking choices support this intensity?"], "causal_reasoning_paths": [{"cause": "Cool/moderate Marlborough maritime climate", "effect": "Aromatic volatile retention; high acidity; thiol expression", "example_in_wine": "Lime, passion fruit, grass aromas remain intact"}, {"cause": "Protective winemaking (stainless steel, low SO₂ at harvest)", "effect": "Preservation of volatile aromatic compounds", "example_in_wine": "Pronounced intensity and fresh character"}, {"cause": "Young varietal character without oak", "effect": "Pure expression of grape and terroir", "example_in_wine": "No tertiary or oak-influenced complexity"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_005','TINTO',1,$lbl$Vino tinto — práctica 1$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_005", "priority": 1, "grape_variety": "Pinot Noir", "region": "Burgundy", "country": "France", "style": "Dry red, pale ruby/garnet colour, high acidity, low to medium tannin, red fruit primary with earthy/tertiary notes.", "expected_sat_observations": {"appearance": ["Pale ruby to garnet colour", "Clear", "Light to medium intensity"], "nose": ["Clean condition", "Medium intensity", "Red fruit (cherry, raspberry, strawberry)", "Possible earthy or tertiary notes (forest floor, mushroom)", "Medium to evolved development"], "palate": ["Dry sweetness", "High acidity", "Low to medium tannin", "Red fruit flavours", "Earthy or gamey notes possible", "Medium finish", "Good structure despite pale colour"], "conclusions": ["Good to Very Good quality", "Drink now or age 3-7 years depending on vintage"]}, "common_student_errors": ["Assuming pale colour means low quality or weak wine", "Overcalling tannin because of acidity perception", "Calling earthy/mushroom notes a fault instead of style characteristic", "Missing the balance between acidity and structure", "Underestimating complexity from bottle age"], "misconceptions_addressed": [{"misconception": "Deep colour always equals high quality", "correction": "Pinot Noir's pale colour is varietal characteristic; quality comes from balance, complexity, and length"}, {"misconception": "High acidity and high tannin go together", "correction": "Pinot Noir demonstrates that high acidity can coexist with low-medium tannin"}, {"misconception": "Earthy/tertiary notes are faults", "correction": "Forest floor, mushroom, and tertiary characters are positive indicators of complexity and bottle age"}], "coaching_hints": ["Focus on balance, complexity, and length rather than colour intensity.", "Never infer structure from colour alone.", "Can you identify red fruit under the earthy characters?", "What indicates quality in a light-coloured red?"], "causal_reasoning_paths": [{"cause": "Pinot Noir thin skins", "effect": "Pale colour and lower tannin extraction", "example_in_wine": "Ruby/garnet colour despite medium-full body"}, {"cause": "Cool Burgundy climate", "effect": "High acidity retention and red fruit (not black fruit)", "example_in_wine": "Cherry and raspberry rather than plum or blackberry"}, {"cause": "Bottle age and reductive evolution", "effect": "Tertiary development of earthy, gamey, forest floor notes", "example_in_wine": "Mushroom and leather aromas in matured wine"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_006','TINTO',1,$lbl$Vino tinto — práctica 2$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_006", "priority": 1, "grape_variety": "Cabernet Sauvignon", "region": "Left Bank Bordeaux / Napa", "country": "France / USA", "style": "Dry, full-bodied, high tannin, black fruit, oak, ageing potential. Deep ruby colour, structured and ageworthy.", "expected_sat_observations": {"appearance": ["Deep ruby colour", "Clear", "Deep intensity"], "nose": ["Clean condition", "Medium to pronounced intensity", "Black fruit (blackcurrant, plum)", "Cedar, mint, herbal notes", "Oak spice (vanilla, clove)", "Medium to evolved development"], "palate": ["Dry sweetness", "Medium to high acidity", "High tannin", "Full body", "Black fruit flavours", "Oak influence (spice, vanilla)", "Long finish", "Structure supports ageing"], "conclusions": ["Good to Excellent quality", "Ready to drink or age 5-15+ years depending on vintage/terroir"]}, "common_student_errors": ["Confusing tannin with acidity", "Assuming high alcohol equals quality", "Missing the relationship between structure and ageing potential", "Ignoring oak as a positive structural element", "Overcalling harshness in young wines"], "misconceptions_addressed": [{"misconception": "Tannin and acidity are the same thing", "correction": "Tannin is structure and texture on palate; acidity is a taste sensation. Both contribute to Cabernet's ageability"}, {"misconception": "Higher alcohol always means better quality", "correction": "Alcohol provides body, but balance of tannin, acidity, and fruit determines quality"}, {"misconception": "Oak in red wine is always visible", "correction": "Well-integrated oak supports structure without being obvious; obvious oak suggests poor integration"}], "coaching_hints": ["What structural elements support ageing?", "How does tannin texture feel on the palate?", "Is oak integrated or dominant?", "Can you assess readiness for drinking based on tannin ripeness?"], "causal_reasoning_paths": [{"cause": "Cabernet Sauvignon thick skins", "effect": "High tannin extraction; deep colour", "example_in_wine": "Full tannin and structure support ageing"}, {"cause": "Warm climate (Bordeaux/Napa)", "effect": "Black fruit (not red fruit); higher alcohol; full body", "example_in_wine": "Blackcurrant and plum rather than cherry"}, {"cause": "Oak maturation and bottle age", "effect": "Tannin integration; oak spice softens; secondary complexity develops", "example_in_wine": "Structure becomes more elegant with age"}], "examination_value": "Very High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_007','TINTO',2,$lbl$Vino tinto — práctica 3$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_007", "priority": 2, "grape_variety": "Merlot", "region": "Right Bank Bordeaux", "country": "France", "style": "Dry, medium/full body, medium/high tannin, plum/red-black fruit, oak possible. Softer tannin profile than Cabernet.", "expected_sat_observations": {"appearance": ["Medium to medium-deep ruby colour", "Clear", "Medium to deep intensity"], "nose": ["Clean condition", "Medium to pronounced intensity", "Plum, red cherry, black fruit", "Chocolate, cedar possible", "Oak spice if present", "Medium development"], "palate": ["Dry sweetness", "Medium acidity", "Medium to medium-high tannin", "Medium to full body", "Plum and cherry flavours", "Oak and chocolate notes", "Medium to long finish", "Softer tannin texture than Cabernet"], "conclusions": ["Good to Very Good quality", "Drink now to medium-term ageing (5-10 years)"]}, "common_student_errors": ["Calling all plum-driven wines low quality", "Missing tannin because it is softer than Cabernet", "Confusing ripe fruit with sweetness", "Underestimating Merlot's structural seriousness", "Assuming Merlot is always simple"], "misconceptions_addressed": [{"misconception": "Merlot is always simple or soft", "correction": "Quality Merlot shows clear structure, complexity, and ageing potential despite softer tannin texture"}, {"misconception": "Plum fruit means inferior quality", "correction": "Plum is a characteristic of Merlot ripeness and terroir, not a quality fault"}, {"misconception": "Soft tannin means short finish", "correction": "Merlot can show medium-long finish with good acidity balance despite low tannin"}], "coaching_hints": ["Compare Merlot's tannin texture to Cabernet — softer, more plush, less astringent.", "Does plum fruit indicate ripeness or overripeness?", "How does acidity support structure without aggressive tannin?", "What indicates ageing potential in this wine?"], "causal_reasoning_paths": [{"cause": "Merlot ripens earlier than Cabernet", "effect": "Plum and red-black fruit rather than blackcurrant; softer tannin; fuller body", "example_in_wine": "Plum and cherry dominate over blackcurrant"}, {"cause": "Right Bank clay/limestone terroir", "effect": "Structural seriousness despite softer fruit character", "example_in_wine": "Pomerol Merlot shows excellent structure despite plush fruit"}, {"cause": "Softer tannin skin character", "effect": "Less astringent mouthfeel; smoother, more velvety texture", "example_in_wine": "Medium tannin feels more integrated than similar Cabernet"}], "examination_value": "High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_008','TINTO',2,$lbl$Vino tinto — práctica 4$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_008", "priority": 2, "grape_variety": "Syrah / Shiraz", "region": "Northern Rhône or Barossa", "country": "France / Australia", "style": "Dry red, medium/full to full body, black fruit, pepper/spice, medium+ tannin. Climate expression varies dramatically.", "expected_sat_observations": {"appearance": ["Deep ruby to purple colour", "Clear", "Deep intensity"], "nose": ["Clean condition", "Medium to pronounced intensity", "Black fruit (blackberry, plum)", "Pepper and spice (white or black pepper)", "Possible licorice or herbal notes", "Development varies by climate"], "palate": ["Dry sweetness", "Medium+ acidity", "Medium+ tannin", "Medium+ to full body", "Black fruit flavours", "Pepper and spice on the palate", "Medium to long finish"], "conclusions": ["Good to Very Good quality", "Moderate to long-term ageing (3-10+ years depending on site)"]}, "common_student_errors": ["Calling all pepper oak-derived (some is varietal)", "Ignoring climate differences and concluding all Syrah tastes the same", "Overusing 'jammy' for all warm-climate reds", "Confusing Syrah and Shiraz as different wines", "Missing the structure under ripe fruit"], "misconceptions_addressed": [{"misconception": "Pepper in wine is always oak-derived", "correction": "Syrah's pepper character is primary varietal expression (white pepper cool-climate; black pepper warm-climate)"}, {"misconception": "Syrah is always spicy and jammy", "correction": "Climate dramatically affects Syrah: cool sites show pepper and fresh black fruit; warm sites show riper, jammy fruit with higher alcohol"}, {"misconception": "Syrah and Shiraz are different grapes", "correction": "Shiraz is the Australian name for Syrah; same grape, different expression due to climate"}], "coaching_hints": ["Is the fruit fresh black fruit or baked/jammy?", "Identify whether pepper is white (cool) or black (warm).", "What climate indicators are present in the wine?", "How does alcohol level reflect the terroir?"], "causal_reasoning_paths": [{"cause": "Cool climate (Northern Rhône)", "effect": "Pepper and freshness retained; moderate alcohol; structured tannin", "example_in_wine": "White pepper and herbal notes; fresh dark fruit; medium alcohol"}, {"cause": "Warm climate (Barossa, warm Rhône)", "effect": "Riper, jammier fruit; higher alcohol; fuller body", "example_in_wine": "Black pepper; baked plum; 14-15% alcohol; full tannin"}, {"cause": "Syrah varietal character", "effect": "Pepper and licorice notes regardless of terroir", "example_in_wine": "Pepper spice is consistent identifier across climates"}], "examination_value": "High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_009','TINTO',2,$lbl$Vino tinto — práctica 5$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_009", "priority": 2, "grape_variety": "Nebbiolo", "region": "Barolo / Barbaresco", "country": "Italy", "style": "Pale garnet, high acid, high tannin, red cherry, rose, dried herbs, tar, earthy notes. Complex and ageworthy.", "expected_sat_observations": {"appearance": ["Pale garnet to tawny colour", "Clear", "Medium intensity (pale despite age)"], "nose": ["Clean condition", "Medium to pronounced intensity", "Red cherry, sour cherry", "Rose and floral notes", "Dried herbs, tar, leather", "Earthy/forest floor notes", "Evolved development (even in youth)"], "palate": ["Dry sweetness", "High acidity", "High tannin", "Medium to medium-full body", "Red cherry and herbal flavours", "Tar and leather notes", "Earthy character", "Long, structured finish"], "conclusions": ["Good to Excellent quality", "Long ageing potential (10-30+ years); normally drink after 3-5 years minimum"]}, "common_student_errors": ["Calling it Pinot Noir due to pale colour", "Underestimating tannin because of pale colour", "Missing the complexity under the austerity", "Confusing rose and floral with sweetness", "Treating tar and leather as faults"], "misconceptions_addressed": [{"misconception": "Pale colour indicates light tannin", "correction": "Nebbiolo demonstrates that high tannin is completely independent of colour; pale colour can hide serious structure"}, {"misconception": "Never infer tannin from colour alone", "correction": "Palate assessment of tannin is essential; colour is unreliable for predicting structure"}, {"misconception": "Tar and earthy notes are faults", "correction": "Tar, leather, and forest floor are positive tertiary characteristics in Nebbiolo"}], "coaching_hints": ["Never infer tannin from colour alone.", "Feel the tannin texture on your palate — is it harsh or structured?", "Notice the pale colour despite full tannin — a key diagnostic feature.", "Can you identify the rose and herbal notes under the structure?"], "causal_reasoning_paths": [{"cause": "Nebbiolo's pale pigment phenolic content", "effect": "Pale colour despite high tannin extraction", "example_in_wine": "Pale garnet with serious astringent mouthfeel"}, {"cause": "Cool Piedmont climate and high acidity", "effect": "Red cherry and sour cherry rather than black fruit", "example_in_wine": "Bright red fruit despite long ageing capacity"}, {"cause": "Long bottle age and reductive evolution", "effect": "Tertiary development of tar, leather, forest floor", "example_in_wine": "Aged Barolo shows pronounced tertiaries"}], "examination_value": "High", "governance": {"safe_for_examiner": false, "formative_only": true, "training_context_only": true, "external_tasting_required": false}}$satw$::jsonb),
('SAT_WINE_010','TINTO',2,$lbl$Vino tinto — práctica 6$lbl$,'canonical_wine',$satw${"id": "SAT_WINE_010", "priority": 2, "grape_variety": "Sangiovese", "region": "Chianti Classico", "country": "Italy", "style": "Dry, high acid, medium/high tannin, sour cherry, herbal, earthy. Oak possible; food-friendly structure.", "expected_sat_observations": {"appearance": ["Medium ruby to garnet colour", "Clear", "Medium intensity"], "nose": ["Clean condition", "Medium intensity", "Sour cherry, red plum", "Herbs (oregano, thyme, sage)", "Earthy/forest floor notes", "Leather possible if aged", "Medium development"], "palate": ["Dry sweetness", "High acidity", "Medium to medium-high tannin", "Medium body", "Sour cherry and herbal flavours", "Savoury character", "Medium to long finish", "Food-friendly structure"], "conclusions": ["Good to Very Good quality", "Drink now to medium-term ageing (3-8 years)"]}, "common_student_errors": ["Confusing with Pinot Noir due to red fruit", "Missing tannin or underestimating its level", "Treating savoury and herbal notes as negative", "Not recognizing the food-pairing philosophy", "Assuming acidity means underripeness"], "misconceptions_addressed": [{"misconception": "High acidity red wines are underripe", "correction": "Sangiovese's high acidity is varietal and regional character, intentional and quality-supporting"}, {"misconception": "Savoury notes are faults", "correction": "Sangiovese's herb and earthy character is positive style expression and terroir identifier"}, {"misconception": "Italian wines are always low in tannin", "correction": "Sangiovese shows serious tannin structure comparable to other quality reds"}], "coaching_hints": ["Link the high acidity and tannin to regional food-wine style.", "Notice how the savoury character complements food.", "Can you identify the sour cherry vs red plum distinction?", "How does acidity contribute to drinkability with food?"], "causal_reasoning_paths": [{"cause": "Sangiovese varietal character", "